// Import ref and computed from 'vue'
import { ref, computed } from 'vue';

// Create the RoleBasedRouteProtection component here
const RoleBasedRouteProtection = {
  setup() {
    // Initialize userRole state here
    const userRole = ref('guest');

    // Define available routes with required roles here
    const routes = [
      { name: 'Home', path: '/', requiredRoles: ['guest', 'user', 'admin'] },
      { name: 'Dashboard', path: '/dashboard', requiredRoles: ['user', 'admin'] },
      { name: 'Admin', path: '/admin', requiredRoles: ['admin'] }
    ];

    // Create computed property for accessible routes here
    const accessibleRoutes = computed(() => {
      return routes.filter(route => route.requiredRoles.includes(userRole.value));
    });

    // Create role change handler here
    const changeRole = (newRole) => {
      userRole.value = newRole;
    };

    return {
      // Expose reactive state to template
      userRole,
      accessibleRoutes,
      changeRole
    }
  },
  template: `
    <div>
      <h2>Role-Based Route Protection</h2>
      <div>
        <label>Current Role:</label>
        <span>{{ userRole }}</span>
      </div>
      <div>
        <button @click="changeRole('guest')">Guest</button>
        <button @click="changeRole('user')">User</button>
        <button @click="changeRole('admin')">Admin</button>
      </div>
      <!-- Add accessible routes list here -->
    </div>
  `
}

